        double A[12];aj_eval(&L,type,e1,e2,Rwc[k],pwc[k],&o,k,0,0,A);
        for(int t=0;t<2;t++)for(int a=0;a<6;a++)Hx[(2*k+t)*MAXD+off+a]=A[6*t+a];
